var ASUNTO = 'MudateYa — una opción para tus compradores al momento de la entrega';
function cuerpoHtml(empresa) {
  return '<div style="font-family:Arial,sans-serif;font-size:14px;color:#22262B;line-height:1.6;max-width:560px">' +
    '<p>Hola,</p>' +
    '<p>Somos MudateYa, un marketplace argentino de mudanzas y fletes: conectamos a quien se muda con mudanceros verificados, presupuestos comparables y pago protegido.</p>' +
    '<p>Te escribimos porque en <strong>' + empresa + '</strong> seguramente tienen, en cada entrega de posesión, un momento en que los compradores necesitan resolver la mudanza — y hoy probablemente no tienen ninguna alternativa que ofrecerles para eso.</p>' +
    '<p>Te dejamos adjunta una breve presentación. Si te interesa, escribinos a contacto@mudateya.ar y lo charlamos.</p>' +
    '<p>Saludos,<br>Equipo MudateYa<br>mudateya.ar</p>' +
    '</div>';
}

module.exports = async function handler(req, res) {
  var esVercelCron = false;
  try { esVercelCron = esCronVercel(req); } catch (e) {}
  var admin = false;
  try { admin = esAdmin(req); } catch (e) {}
  if (!esVercelCron && !admin) return res.status(401).json({ error: 'No autorizado' });
  if (!process.env.RESEND_API_KEY) return res.status(200).json({ error: 'sin RESEND_API_KEY' });

  var apply = esVercelCron || (req.method === 'POST' && req.body && req.body.apply === true);

  if (!apply) {
    return res.status(200).json({
      ok: true,
      modo: 'preview',
      total: DESTINATARIOS.length,
      destinatarios: DESTINATARIOS.map(function (d) {
        return { empresa: d.empresa, email: d.email, archivo: d.archivo };
      }),
      nota: 'POST con {"apply":true} para mandarlos ahora mismo (o esperá al cron de las 9am ART).',
    });
  }

  var yaEnviado = await getJSON(FLAG_ENVIADO);
  if (yaEnviado) {
    return res.status(200).json({ ok: true, yaEnviado: true, cuando: yaEnviado, nota: 'Ya se mandó antes, no se repite.' });
  }

  var { Resend } = require('resend');
  var resend = new Resend(process.env.RESEND_API_KEY);
  var resultados = [];

  for (var i = 0; i < DESTINATARIOS.length; i++) {
    var d = DESTINATARIOS[i];
    try {
      var linkB = linkBaja(d.email, 'propuestas-desarrolladoras');
      var envio = await resend.emails.send({
        from: 'MudateYa <contacto@mudateya.ar>',
        to: d.email,
        subject: ASUNTO,
        html: cuerpoHtml(d.empresa),
        attachments: [{ filename: d.archivo, content: d.pdfBase64 }],
        headers: {
          'List-Unsubscribe': '<mailto:hola@mudateya.ar?subject=BAJA>, <' + linkB + '>',
          'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
        },
      });
      if (envio && envio.error) throw new Error(envio.error.message || JSON.stringify(envio.error));
      resultados.push({ empresa: d.empresa, email: d.email, ok: true, id: (envio && envio.data && envio.data.id) || null });
    } catch (e) {
      resultados.push({ empresa: d.empresa, email: d.email, ok: false, error: e.message });
    }
    await new Promise(function (ok) { setTimeout(ok, 150); });
  }

  await setJSON(FLAG_ENVIADO, new Date().toISOString());
  var enviados = resultados.filter(function (r) { return r.ok; }).length;
  return res.status(200).json({ ok: true, total: resultados.length, enviados: enviados, fallidos: resultados.length - enviados, resultados });
};
